<script lang="ts">
	import PageLayout from '$components/PageLayout.svelte';
	import { diskSelectionData } from '$lib/state.svelte';
	// @ts-expect-error — generated by Wails
	import { StartInstallation, GetDryRun } from '@wails/go/gui/App.js';
	// @ts-expect-error — generated by Wails
	import { EventsOn, LogInfo } from '@wails/runtime/runtime.js';

	// Event names matching backend constants
	const EVENT_PROGRESS = 'installation:progress';
	const EVENT_COMPLETE = 'installation:complete';
	const EVENT_ERROR    = 'installation:error';

	let currentStep = $state(0);
	let currentStepLabel = $state('');
	let progress = $state(0);
	let isRunning = $state(false);
	let isComplete = $state(false);
	let hasTransitioned = $state(false);
	let elapsedSeconds = $state(0);
	let errorMessage = $state('');
	let isDryRun = $state(false);



	// Countdown timer for elapsed time display
	$effect(() => {
		if (!isRunning) return;

		const interval = setInterval(() => {
			elapsedSeconds++;
		}, 1000);

		return () => clearInterval(interval);
	});

	// Listen for installation events from the backend
	$effect(() => {
		const handleProgress = (data: { label: string; percent: number; phase: string }) => {
			// Strip any timestamp/percentage prefix — only keep the step name
			let cleanLabel = data.label;
			// Remove leading [HH:MM:SS] if present
			cleanLabel = cleanLabel.replace(/^\[\d{2}:\d{2}:\d{2}\]\s*/, '');
			// Remove leading [N%] if present
			cleanLabel = cleanLabel.replace(/^\[\d+%\]\s*/, '');
			// Remove leading => if present
			cleanLabel = cleanLabel.replace(/^=>\s*/, '');
			cleanLabel = cleanLabel.trim();

			if (cleanLabel !== currentStepLabel) {
				currentStepLabel = cleanLabel;
				progress = 0;
			}
			if (data.phase === 'running') {
				currentStep = data.percent;
				if (data.percent >= progress) {
					progress = data.percent;
				}
				errorMessage = '';
			} else if (data.phase === 'done') {
				currentStep = data.percent;
				progress = 100;
			}
		};

		const handleComplete = (data: { label: string; percent: number; phase: string }) => {
			isRunning = false;
			isComplete = true;
			progress = 100;
			errorMessage = '';
			LogInfo('[InstallationPage] Installation complete');
		};

		const handleError = (data: { label: string; percent: number; phase: string }, message: string) => {
			isRunning = false;
			errorMessage = message;
			LogInfo(`[InstallationPage] Installation error: ${message}`);
		};

		const offProgress = EventsOn(EVENT_PROGRESS, handleProgress);
		const offComplete = EventsOn(EVENT_COMPLETE, handleComplete);
		const offError = EventsOn(EVENT_ERROR, handleError);

		return () => {
			offProgress();
			offComplete();
			offError();
		};
	});

	// Auto-transition to Finish page when installation is done
	$effect(() => {
		if (!isComplete || hasTransitioned) return;
		hasTransitioned = true;
		setTimeout(() => {
			document.dispatchEvent(new CustomEvent('go-next', { cancelable: true }));
		}, 1000);
	});

	// Auto-start installation when page is reached
	async function init(): Promise<void> {
		isDryRun = await GetDryRun();
		isRunning = true;
		try {
			await StartInstallation();
		} catch (err) {
			isRunning = false;
			errorMessage = err instanceof Error ? err.message : 'Failed to start installation';
			LogInfo(`[InstallationPage] ${errorMessage}`);
		}
	}

	init();

	function formatTime(s: number): string {
		const mins = Math.floor(s / 60);
		const secs = s % 60;
		return `${mins}:${secs.toString().padStart(2, '0')}`;
	}

	const currentLabel = $derived(
		isComplete ? 'Installation completed!' :
		errorMessage ? errorMessage :
		currentStepLabel || 'Initializing...'
	);
</script>

<PageLayout title="Installing AestheticOS">
	<div class="installation">
		<!-- Target disk info -->
		{#if diskSelectionData.diskId}
			<div class="disk-info">
				Target: <strong>{diskSelectionData.diskId}</strong>
			</div>
		{/if}

		<!-- Progress bar -->
		{#if isDryRun}
			<span class="dry-run-badge">DRY RUN</span>
			{/if}
			<div class="progress-container">
			<div class="progress-bar-bg">
				<div
					class:running={isRunning}
					class="progress-bar-fill"
					style="--progress: {progress}%"
				></div>
			</div>
			<div class="progress-info">
				<span class="progress-percent">{progress}%</span>
				<span class="progress-time">
					{formatTime(elapsedSeconds)}
				</span>
			</div>
		</div>

		<!-- Current step label -->
		<p class="step-label">{currentLabel}</p>

	</div>
</PageLayout>

<style>
	.installation {
		display: flex;
		flex-direction: column;
		align-items: center;
		gap: 16px;
		width: 100%;
	}

	/* ── Dry-run badge ── */
	.dry-run-badge {
		padding: 4px 12px;
		background: var(--color-warning);
		color: white;
		font-size: var(--font-size-sm);
		font-weight: var(--font-weight-700);
		border-radius: var(--radius-sm);
		letter-spacing: 0.05em;
	}

	/* ── Progress bar ── */
	.progress-container {
		width: 100%;
		display: flex;
		flex-direction: column;
		gap: 6px;
	}

	.progress-bar-bg {
		width: 100%;
		height: 14px;
		background: rgba(255, 255, 255, 0.15);
		border-radius: 999px;
		overflow: hidden;
	}

	.progress-bar-fill {
		height: 100%;
		width: var(--progress);
		background: linear-gradient(90deg, var(--color-primary), var(--color-sky));
		border-radius: 999px;
		transition: width 0.5s ease;
		position: relative;
		overflow: hidden;
	}

	/* Sliding highlight — active while a step is running */
	.progress-bar-fill.running::after {
		content: '';
		position: absolute;
		top: 0;
		left: -40%;
		width: 40%;
		height: 100%;
		background: linear-gradient(90deg, transparent, rgba(255,255,255,0.25), transparent);
		animation: slide 1.8s ease-in-out infinite;
	}

	@keyframes slide {
		0% {
			left: -40%;
		}
		100% {
			left: 100%;
		}
	}

	.progress-info {
		display: flex;
		justify-content: space-between;
		font-size: var(--font-size-sm);
		color: var(--color-text-muted);
	}

	.progress-percent {
		font-weight: var(--font-weight-700);
		color: var(--color-primary);
	}

	/* ── Step label ── */
	.step-label {
		margin: 0;
		font-size: 1.05rem;
		font-weight: var(--font-weight-600);
		color: var(--color-text);
		min-height: 1.5em;
		transition: opacity 0.2s;
	}

	/* ── Disk info ── */
	.disk-info {
		font-size: var(--font-size-sm);
		color: var(--color-text-muted);
	}

	.disk-info strong {
		color: var(--color-text);
	}

</style>
